import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1792298442000}`),a={name:`introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>曦寒打印设计器（XiHan.PrintDesigner）是一款框架无关的打印设计器：以原生 Web Components 交付，可视化设计打印模板，在浏览器里按数据分页、预览与打印；配合本地打印客户端，还能不弹对话框直接打到指定的打印机。属于曦寒懿（XiHanFun）开源生态，采用 MIT 授权。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to “能做什么”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th></tr></thead><tbody><tr><td>设计与修改模板</td><td><code>&lt;xh-print-designer&gt;</code>：物料面板、标尺与参考线、吸附对齐、属性面板、问题列表、表格编辑、撤销重做，可切到预览态</td></tr><tr><td>在业务页面里预览、打印</td><td><code>&lt;xh-print-preview&gt;</code>：按数据排出全部输出页逐页显示，调起浏览器的打印对话框</td></tr><tr><td>不显示预览直接打印</td><td><code>printDocument(schema, data)</code>：在隐藏的 iframe 里排版并调起打印对话框</td></tr><tr><td>静默打印、原始指令、导出 PDF</td><td>本地打印客户端，经 <code>@xihan-print/runtime/client</code> 连接</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><ul><li><strong>框架无关</strong>：以原生 Web Components 交付，不绑定任何前端框架。元素用 Light DOM，样式只消费 <a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan.UI</a> 的设计令牌。</li><li><strong>零第三方依赖</strong>：运行时只依赖 <code>@xihan-print/*</code> 与 <code>@xihan-ui/*</code>，条码、二维码、受限表达式与格式化都来自 XiHan.UI。</li><li><strong>模板即数据</strong>：模板是纯 JSON，不含也不执行任何代码。需要计算的地方用受限表达式，导入模板不会带来脚本注入。</li><li><strong>数据由使用方掌控</strong>：组件不发网络请求。模板存在哪里、数据从哪里取、谁能改模板，都由使用方决定，经属性与事件交给组件。</li><li><strong>没有全局状态</strong>：不往 <code>window</code> 上挂对象，不读写固定键名的本地存储，同一页面放多个实例互不影响。</li></ul><h2 id="包与入口" tabindex="-1">包与入口 <a class="header-anchor" href="#包与入口" aria-label="Permalink to “包与入口”">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>内容</th></tr></thead><tbody><tr><td><code>@xihan-print/core</code></td><td>模板的类型定义、校验、编辑操作与分页算法。纯 TypeScript，不依赖 DOM，浏览器与 Node.js 里都能用</td></tr><tr><td><code>@xihan-print/runtime</code></td><td>业务页面用的 <code>&lt;xh-print-preview&gt;</code>、<code>printDocument</code> 与浏览器打印，样式在 <code>@xihan-print/runtime/style.css</code></td></tr><tr><td><code>@xihan-print/runtime/client</code></td><td>连接本地打印客户端：静默打印、原始指令、导出 PDF；不用客户端的页面不会加载这部分代码</td></tr><tr><td><code>@xihan-print/runtime/locale</code></td><td>各语言的语言包，如 <code>printZhCN</code>、<code>printJaJP</code>，与 XiHan.UI 的内建语言包一一对应，预览与设计器共用</td></tr><tr><td><code>@xihan-print/designer</code></td><td><code>&lt;xh-print-designer&gt;</code>，样式在 <code>@xihan-print/designer/style.css</code></td></tr></tbody></table><p>依赖方向固定为 <code>designer → runtime → core</code>。业务页面只需要 runtime，设计器只在需要编辑模板的地方加载。</p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设计器 &lt;xh-print-designer&gt;</span></span>
<span class="line"><span>  │  schema-change / save 事件</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>宿主保存模板 JSON（数据库、文件，由宿主决定）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>业务页面取模板与数据</span></span>
<span class="line"><span>  ├─ &lt;xh-print-preview&gt; 或 printDocument ──▶ 浏览器打印对话框</span></span>
<span class="line"><span>  └─ @xihan-print/runtime/client ──▶ 本地打印客户端 ──▶ 打印机 / PDF</span></span></code></pre></div><ol><li>设计：在设计器里编辑模板，设计器派发 <code>schema-change</code> 与 <code>save</code>，宿主把模板 JSON 存起来。</li><li>打印：业务页面取出模板与数据，交给 <code>&lt;xh-print-preview&gt;</code> 预览与打印，或者直接调用 <code>printDocument</code>。</li><li>静默打印：装了本地打印客户端时，交给客户端打到指定的打印机；连不上客户端时退回浏览器的打印对话框。</li></ol><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to “运行环境”">​</a></h2><ul><li><code>@xihan-print/core</code> 不依赖 DOM，可以在浏览器、Node.js 或其它 JavaScript 运行环境里校验模板、排出输出页。</li><li><code>@xihan-print/runtime</code> 与 <code>@xihan-print/designer</code> 要在支持 Custom Elements 的浏览器里运行，文字度量缺省用 Canvas 2D。</li><li>本地打印客户端是 Windows 托盘程序，有 x64 与 arm64 两种安装包，渲染用系统的 WebView2 运行时。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./quickstart">快速开始</a>：在任意前端项目里装包、渲染一张模板并打印。</li><li><a href="./guide/template">模板结构</a>：页面、页眉页脚、元素与表格。</li><li><a href="./guide/rich-text">富文本</a>：带格式的文字、字段里的 HTML 与存量模板的迁移。</li></ul>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};